import os, ast, json
from pathlib import Path
from collections import defaultdict, deque

inputs = Path('/inputs')
work = Path('/work')

# Read inert reference text as requested
_ = (inputs / 'smell-catalog.md').read_text(encoding='utf-8')

# Collect top-level Python source files with exclusions
py_files = []
for p in inputs.iterdir():
    if not p.is_file():
        continue
    name = p.name
    if not name.endswith('.py'):
        continue
    if name == '__init__.py':
        continue
    if name.startswith('test_'):
        continue
    if name.endswith('_test.py'):
        continue
    py_files.append(p)

py_files.sort(key=lambda p: p.name)

included_basenames = [p.name for p in py_files]
included_set = set(included_basenames)
stems = {p.stem: p.name for p in py_files}

line_counts = {}
for p in py_files:
    text = p.read_text(encoding='utf-8')
    line_counts[p.name] = len(text.splitlines())


def first_component(module_name: str):
    if not module_name:
        return None
    return module_name.split('.')[0]


def maybe_add_edge(target_stem, current_basename, out_set):
    if not target_stem:
        return
    target_basename = f"{target_stem}.py"
    if target_basename == current_basename:
        return
    if target_basename in included_set:
        out_set.add(target_basename)

# Build static import graph
imports_graph = {p.name: set() for p in py_files}

for p in py_files:
    text = p.read_text(encoding='utf-8')
    tree = ast.parse(text, filename=str(p))
    out = imports_graph[p.name]

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                name = alias.name
                # explicit absolute imports under skillc.frontend
                if name == 'skillc.frontend' or name.startswith('skillc.frontend.'):
                    remainder = name[len('skillc.frontend'):].lstrip('.')
                    comp = first_component(remainder)
                    maybe_add_edge(comp, p.name, out)
        elif isinstance(node, ast.ImportFrom):
            level = node.level or 0
            module = node.module

            if level == 1:
                # from .module import ...
                if module:
                    comp = first_component(module)
                    maybe_add_edge(comp, p.name, out)
                else:
                    # from . import module_a, module_b
                    for alias in node.names:
                        if alias.name == '*':
                            continue
                        comp = first_component(alias.name)
                        maybe_add_edge(comp, p.name, out)
            elif level == 0:
                # explicit absolute-package forms
                if module == 'skillc.frontend' or (module and module.startswith('skillc.frontend.')):
                    if module == 'skillc.frontend':
                        # from skillc.frontend import module
                        for alias in node.names:
                            if alias.name == '*':
                                continue
                            comp = first_component(alias.name)
                            maybe_add_edge(comp, p.name, out)
                    else:
                        remainder = module[len('skillc.frontend'):].lstrip('.')
                        comp = first_component(remainder)
                        maybe_add_edge(comp, p.name, out)
            # ignore level > 1 and all other imports

# files list
files_rows = []
for name in sorted(included_basenames):
    files_rows.append({
        'name': name,
        'lines': line_counts[name],
        'imports': sorted(imports_graph[name])
    })

# prefix clusters
stem_list = sorted(stems.keys())
prefix_to_members = {}
for stem in stem_list:
    for i in range(4, len(stem) + 1):
        pref = stem[:i]
        members = tuple(sorted(s for s in stem_list if s.startswith(pref)))
        if len(members) >= 3:
            prefix_to_members[pref] = members

# Group by member set, choose LCP as representative
members_to_prefixes = defaultdict(list)
for pref, members in prefix_to_members.items():
    members_to_prefixes[members].append(pref)


def lcp(strings):
    if not strings:
        return ''
    s1 = min(strings)
    s2 = max(strings)
    i = 0
    while i < len(s1) and i < len(s2) and s1[i] == s2[i]:
        i += 1
    return s1[:i]

prefix_rows = []
for members, _prefs in members_to_prefixes.items():
    rep = lcp(list(members))
    # rep should be >=4 based on construction; guard anyway
    if len(rep) < 4:
        continue
    files = [f"{m}.py" for m in members]
    total = sum(line_counts[f] for f in files)
    prefix_rows.append({
        'prefix': rep,
        'files': sorted(files),
        'lines': total
    })

prefix_rows.sort(key=lambda r: r['prefix'])

# import tree clusters

def reachable_from(root):
    seen = set()
    stack = [root]
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in imports_graph.get(cur, ()):
            if nxt not in seen:
                stack.append(nxt)
    return seen

import_tree_rows = []
for root in sorted(included_basenames):
    direct = imports_graph[root]
    if len(direct) < 3:
        continue
    reach = reachable_from(root)
    if len(reach) >= 5:
        files = sorted(reach)
        total = sum(line_counts[f] for f in files)
        import_tree_rows.append({
            'root': root,
            'files': files,
            'lines': total
        })

import_tree_rows.sort(key=lambda r: r['root'])

result = {
    'files': files_rows,
    'prefix_clusters': prefix_rows,
    'import_tree_clusters': import_tree_rows,
}

out_path = work / 'layout.json'
out_path.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

print(f'wrote {out_path}')
print(out_path.read_text(encoding='utf-8'))
